#!/usr/bin/env python3
# Oak's Parcel + Pokedex quest: Viridian Mart parcel hand-off, Oak's Lab
# TEXT_OAKSLAB_OAK1 delivery/Pokedex cutscene, and 5 runner verbs.
# Ported from ~/gen1recomp/data/scripts/oaks_lab.lua + story.lua M.VIRIDIAN_MART.
# Self-verifying: every anchor must match exactly once or nothing is written.
import base64, json, os, sys

ROOT = os.path.expanduser("~/pocket-voxel")
if not os.path.isdir(os.path.join(ROOT, "voxelmon")):
    ROOT = os.getcwd()

DATA = json.loads(base64.b64decode(
""
))
hunks = DATA["hunks"]; sentinels = DATA["sentinels"]

# 1) idempotency: refuse if any part is already applied
for rel, marker in sentinels.items():
    p = os.path.join(ROOT, rel)
    if os.path.isfile(p) and marker in open(p, encoding="utf-8").read():
        sys.exit("ABORT: '{}' already present in {} -- patch already applied.".format(marker, rel))

# 2) verify EVERY anchor matches exactly once BEFORE writing anything
files = {}
for h in hunks:
    p = os.path.join(ROOT, h["path"])
    if p not in files:
        if not os.path.isfile(p): sys.exit("ABORT: missing file " + h["path"])
        files[p] = open(p, encoding="utf-8").read()
    old = base64.b64decode(h["old"]).decode()
    n = files[p].count(old)
    if n != 1:
        sys.exit("ABORT: anchor in {} matched {} times (need 1) -- file drifted, nothing written.".format(h["path"], n))

# 3) apply in-memory, then write
for h in hunks:
    p = os.path.join(ROOT, h["path"])
    old = base64.b64decode(h["old"]).decode()
    new = base64.b64decode(h["new"]).decode()
    files[p] = files[p].replace(old, new, 1)

conf = {}
for p, text in files.items():
    open(p, "w", encoding="utf-8").write(text)
    conf[os.path.relpath(p, ROOT)] = {"bytes": len(text)}
print("PATCHED (root=" + ROOT + "):")
print(json.dumps(conf, indent=2))
print("verbs +5: check_item take_item clear_flag check_dex_owned dex_rating")
print("scripts: VIRIDIAN_MART.onStep (parcel), OAKS_LAB.talk.TEXT_OAKSLAB_OAK1 (pokedex)")
